with UserParticipation as (
    select u.Id as UserId,
           count(distinct p.Id) as TotalPosts,
           sum(case when p.PostTypeId=1 then 1 else 0 end) as QuestionsCount,
           sum(case when p.PostTypeId=2 then 1 else 0 end) as AnswersCount,
           coalesce(sum(v.TotalVotes),0) as TotalVotesReceived,
           first_value(u.Reputation) over(partition by u.Id order by null) as ReputationAlways,
       dense_rank() over(partition by community_ids.maxBadgeClass order by coalesce(u.Reputation,0) desc) rankByRepPerClass  
    from Users u
    left join Posts p on p.OwnerUserId = u.Id
    left join (
        select p.PostTypeId, p.OwnerUserId, count(*) TotalVotes
        from Posts p
        join Votes v2 on v2.PostId = p.Id 
        where v2.VoteTypeId in (2,3) 
        group by p.PostTypeId, p.OwnerUserId
    ) v TotalUserVotes on v.TotalUserVotes.OwnerUserId = u.Id
    cross join lateral (
